<template>
  <ul
    v-show="visible"
    ref="groupRef"
    :class="[
      ns.be('group', 'wrap'),
      ns.is('multiple', select.props.multiple),
      ns.is('selection-group', true),
    ]"
  >
    <li
      v-if="hasVisibleSelectedOptions"
      :class="[ns.be('group', 'business-title'), ns.is('selected-group')]"
    >
      {{ label }}
    </li>
    <li
      v-if="hasVisibleUnselectedOptions"
      :class="[ns.be('group', 'business-title'), ns.is('unselected-group')]"
    >
      {{ label }}
    </li>
    <slot />
  </ul>
</template>

<script lang="ts">
import {
  computed,
  defineComponent,
  getCurrentInstance,
  inject,
  isVNode,
  onMounted,
  provide,
  reactive,
  ref,
  toRefs,
  unref,
} from 'vue'
import { useMutationObserver } from '@vueuse/core'
import { ensureArray, isArray } from '@element-plus/utils'
import { useNamespace } from '@element-plus/hooks'
import { selectGroupKey, selectKey } from './token'

import type { Component, VNode, VNodeArrayChildren } from 'vue'
import type { OptionInternalInstance, OptionPublicInstance } from './type'

export default defineComponent({
  name: 'ElOptionGroup',
  componentName: 'ElOptionGroup',

  props: {
    /**
     * @description name of the group
     */
    label: String,
    /**
     * @description whether to disable all options in this group
     */
    disabled: Boolean,
  },
  setup(props) {
    const select = inject(selectKey)!
    const ns = useNamespace('select')
    const groupRef = ref<HTMLElement>()
    const instance = getCurrentInstance()!
    const children = ref<OptionPublicInstance[]>([])

    provide(
      selectGroupKey,
      reactive({
        ...toRefs(props),
      })
    )

    const visible = computed(() =>
      children.value.some((option) => option.visible === true)
    )
    const hasVisibleSelectedOptions = computed(() =>
      children.value.some(
        (option) => option.visible === true && unref(option.itemSelected)
      )
    )
    const hasVisibleUnselectedOptions = computed(() =>
      children.value.some(
        (option) => option.visible === true && !unref(option.itemSelected)
      )
    )

    const isOption = (
      node: VNode
    ): node is VNode & { component: OptionInternalInstance } =>
      (node.type as Component).name === 'ElOption' && !!node.component?.proxy

    // get all instances of options
    const flattedChildren = (node: VNode | VNodeArrayChildren) => {
      const nodes = ensureArray(node) as VNode[] | VNodeArrayChildren
      const children: OptionPublicInstance[] = []

      nodes.forEach((child) => {
        if (!isVNode(child)) return

        if (isOption(child)) {
          children.push(child.component.proxy)
        } else if (isArray(child.children) && child.children.length) {
          children.push(...flattedChildren(child.children))
        } else if (child.component?.subTree) {
          children.push(...flattedChildren(child.component.subTree))
        }
      })

      return children
    }

    const updateChildren = () => {
      children.value = flattedChildren(instance.subTree)
    }

    onMounted(() => {
      updateChildren()
    })

    useMutationObserver(groupRef, updateChildren, {
      attributes: true,
      subtree: true,
      childList: true,
    })

    return {
      groupRef,
      select,
      visible,
      hasVisibleSelectedOptions,
      hasVisibleUnselectedOptions,
      ns,
    }
  },
})
</script>
